WITH agg AS ( SELECT a.expert_id AS agent_id, CAST( date_add( 'day', 4, date_trunc('week', CAST(a."date" AS TIMESTAMP)) ) AS DATE ) AS period, LOWER(a.metric) AS metric, a.icp_client, a.site, SUM(a.numerator) AS numerator, SUM(a.denominator) AS denominator FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-06-20' AND DATE '2026-07-31' AND LOWER(a.metric) IN ( 'client transfers','resolution rate','ocr','hold time','talk time','callback_rate','cancellation rate','erp','expert 5star','nsp100','crt' ) AND LOWER(a.icp_client) IN ( 'pss-verizon','pss-at&t','mob-verizon','mob-at&t' ) GROUP BY 1,2,3,4,5 ) SELECT agent_id, CAST(period AS DATE) AS week_ending, 'all' as call_type, metric, icp_client, site, CAST(numerator AS DOUBLE) AS numerator, CAST(denominator AS DOUBLE) AS denominator, ROUND( COALESCE( CAST(numerator AS DOUBLE) / NULLIF(CAST(denominator AS DOUBLE), 0.0), 0.000 ), 3 ) AS calc FROM agg
